{"files":[{"path":"logscan/parse.py","content":""""Parsing for timestamped log records."""

import re
from datetime import datetime, timezone


_LINE = re.compile(
    r"([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z) "
    r"([Dd][Ee][Bb][Uu][Gg]|[Ii][Nn][Ff][Oo]|[Ww][Aa][Rr][Nn]|[Ee][Rr][Rr][Oo][Rr]) "
    r"(\S+?): (.*)"
)


def parse_line(line: str) -> dict | None:
    """Return a normalized record, or None when the line is malformed."""
    if not isinstance(line, str):
        return None
    match = _LINE.fullmatch(line.strip())
    if match is None:
        return None
    timestamp, level, component, message = match.groups()
    try:
        ts = datetime.strptime(timestamp, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None
    return {
        "ts": ts,
        "level": level.upper(),
        "component": component,
        "message": message.strip(),
    }
"}]}

